"""Fixed bundle offers; all prices and savings are in cents."""

from .catalog import product


# code -> (name, {sku: quantity}, price in cents)
BUNDLES = {
    'STARTER': ('Starter pack', {'MUG': 1, 'TEE': 1}, 3299),
    'TRAVEL': ('Travel set', {'CAP': 1, 'BAG': 1}, 2099),
}


def apply_bundles(items):
    """Return (bundle counts, remaining items) without changing the input.

    Consume each offer as many times as possible, in code order.
    Input items use the cart's uppercase SKUs and nonnegative quantities.
    """
    rest = {sku: qty for sku, qty in items.items() if qty}
    bundles = {}
    for code in sorted(BUNDLES):
        _, components, _ = BUNDLES[code]
        count = min(rest.get(sku, 0) // qty for sku, qty in components.items())
        if count:
            bundles[code] = count
            for sku, qty in components.items():
                rest[sku] -= count * qty
                if rest[sku] == 0:
                    del rest[sku]
    return bundles, rest


def bundle_savings(code):
    """Return the saving in cents for one bundle (KeyError if unknown)."""
    _, components, price = BUNDLES[code]
    return sum(product(sku)[1] * qty for sku, qty in components.items()) - price

import unittest
from unittest.mock import patch

from shop.bundles import BUNDLES, apply_bundles, bundle_savings


class BundlesTest(unittest.TestCase):
    def test_fixed_offers_and_savings(self):
        self.assertEqual(BUNDLES, {
            'STARTER': ('Starter pack', {'MUG': 1, 'TEE': 1}, 3299),
            'TRAVEL': ('Travel set', {'CAP': 1, 'BAG': 1}, 2099),
        })
        self.assertEqual(bundle_savings('STARTER'), 450)
        self.assertEqual(bundle_savings('TRAVEL'), 399)
        with self.assertRaises(KeyError):
            bundle_savings('UNKNOWN')

    def test_empty_and_incomplete_carts(self):
        for items in ({}, {'MUG': 2}, {'TEE': 1, 'BAG': 3}):
            with self.subTest(items=items):
                self.assertEqual(apply_bundles(items), ({}, items))

    def test_exact_bundles(self):
        self.assertEqual(
            apply_bundles({'MUG': 1, 'TEE': 1, 'CAP': 1, 'BAG': 1}),
            ({'STARTER': 1, 'TRAVEL': 1}, {}),
        )

    def test_multiple_bundles_and_leftovers_preserve_input(self):
        items = {'MUG': 3, 'TEE': 2, 'CAP': 2, 'BAG': 4}
        original = items.copy()
        self.assertEqual(apply_bundles(items), (
            {'STARTER': 2, 'TRAVEL': 2}, {'MUG': 1, 'BAG': 2},
        ))
        self.assertEqual(items, original)

    def test_zero_quantities_are_omitted(self):
        self.assertEqual(apply_bundles({'MUG': 0, 'TEE': 1}), ({}, {'TEE': 1}))

    def test_alphabetical_priority_and_component_quantities(self):
        # Reverse insertion order and shared products make priority observable.
        offers = {
            'Z': ('Later', {'MUG': 1, 'TEE': 1}, 3000),
            'A': ('First', {'MUG': 2}, 2000),
        }
        with patch.dict(BUNDLES, offers, clear=True):
            bundles, rest = apply_bundles({'MUG': 5, 'TEE': 3})
            self.assertEqual(list(bundles.items()), [('A', 2), ('Z', 1)])
            self.assertEqual(rest, {'TEE': 2})
            self.assertEqual(bundle_savings('A'), 500)


if __name__ == '__main__':
    unittest.main()
